{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "鳥はなんで空をとべるの？",
        "猫はなんでずっとねてるの？",
        "君はどんな今日を生きるの？",
        "ぜんぶ ぜんぶ ぜんぶ",
        "さがしにゆこう"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "朝はなんで僕を照らすの？",
        "夜はなんで寂しくなるの？",
        "かなしいことははんぶんこ",
        "できたらいいのにね"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "笑ったり悩んでみたり",
        "この広い世界のすみっこで",
        "僕らでうちゅうのふしぎ",
        "解き明かしてみよう"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "星はなんで輝いてるの",
        "雲はどうして空を泳ぐの",
        "人はなんで夢を描くの",
        "答えなんてないのかな"
      ]
    },
    {
      "section": "D1",
      "lyrics": [
        "いつかこんなちいさなうたは",
        "きみはきっとわすれちゃうけど",
        "ぼくはずっとおぼえているよ",
        "おとなになってもね"
      ]
    },
    {
      "section": "V3",
      "lyrics": [
        "今日はどんな話をしよう？",
        "君とどんな歌を歌おう？",
        "誰もまだ知らない花も"
      ]
    },
    {
      "section": "O1",
      "lyrics": [
        "ぜんぶ ぜんぶ ぜんぶ",
        "さがしにゆこう",
        "ぜんぶ ぜんぶ ぜんぶ",
        "さがしにゆこう"
      ]
    }
  ],
  "section": "V2",
  "phrases": [
    {
      "id": "V2-01",
      "ja": "朝はなんで僕を照らすの？",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        3,
        2,
        3,
        4
      ]
    },
    {
      "id": "V2-02",
      "ja": "夜はなんで寂しくなるの？",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        3,
        2,
        3,
        4
      ]
    },
    {
      "id": "V2-03",
      "ja": "かなしいことははんぶんこ",
      "budget": {
        "min": 9,
        "max": 9
      },
      "pattern": [
        3,
        3,
        3
      ]
    },
    {
      "id": "V2-04",
      "ja": "できたらいいのにね",
      "budget": {
        "min": 9,
        "max": 9
      },
      "pattern": [
        4,
        2,
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "晨光为什么落在我肩上"
        },
        {
          "id": "V2-02",
          "zh": "夜色为什么让人心发慌"
        },
        {
          "id": "V2-03",
          "zh": "悲伤分我一半好不好"
        },
        {
          "id": "V2-04",
          "zh": "若能这样该多好"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "早晨呀 为何 偏照着 我的眼睛"
        },
        {
          "id": "V2-02",
          "zh": "夜晚呀 为何 熄了灯 就变空荡"
        },
        {
          "id": "V2-03",
          "zh": "难过呀 掰一半 分给你"
        },
        {
          "id": "V2-04",
          "zh": "能这样就 多好 你说呢"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "为何晨光总将我照亮？"
        },
        {
          "id": "V2-02",
          "zh": "为何夜晚总让人心伤？"
        },
        {
          "id": "V2-03",
          "zh": "悲伤的事各分一半"
        },
        {
          "id": "V2-04",
          "zh": "若能那样该多好"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "阳光啊 为何 偏爱地 落我肩上"
        },
        {
          "id": "V2-02",
          "zh": "夜色啊 为何 把房间 吹得空荡"
        },
        {
          "id": "V2-03",
          "zh": "把难过 掰两半 各一半"
        },
        {
          "id": "V2-04",
          "zh": "要是能够 一人 分一半"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "清晨为何要将我照亮？"
        },
        {
          "id": "V2-02",
          "zh": "夜晚为何会变得寂凉？"
        },
        {
          "id": "V2-03",
          "zh": "悲伤的事情对半分吧"
        },
        {
          "id": "V2-04",
          "zh": "若能如此该有多好啊"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "清晨为什么总把我照亮"
        },
        {
          "id": "V2-02",
          "zh": "夜晚为什么总让人心慌"
        },
        {
          "id": "V2-03",
          "zh": "悲伤的事 分你一半"
        },
        {
          "id": "V2-04",
          "zh": "能这样就好了呢"
        }
      ]
    }
  ]
}

